#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>
#include <time.h>

/* 
 * Demonstrates the use of stat() to retrieve file metadata.
 * Checks the current executable file.
 */
int main(int argc, char *argv[]) {
    struct stat sb;
    const char *filepath = (argc > 1) ? argv[1] : argv[0];

    if (filepath == NULL) {
        fprintf(stderr, "Error: Could not determine executable path.\n");
        return 1;
    }

    /* Attempt to retrieve status information */
    if (stat(filepath, &sb) == -1) {
        perror("stat failed");
        return 1;
    }

    printf("\n--- File Status for %s ---\n", filepath);
    printf("File Size: %lld bytes\n", (long long)sb.st_size);
    printf("Inode number: %ld\n", (long)sb.st_ino);
    printf("Owner UID: %d\n", sb.st_uid);

    /* Print simple permissions (octal) */
    printf("Permissions: 0%o\n", sb.st_mode & 0777);

    /* Print last modification time */
    printf("Last Modified: %s", ctime(&sb.st_mtime));

    if (S_ISREG(sb.st_mode)) {
        printf("File Type: Regular file\n");
    } else if (S_ISDIR(sb.st_mode)) {
        printf("File Type: Directory\n");
    }

    return 0;
}
